<script setup lang="ts">
import {sizeGroups} from '~/utils/sizes';import products from '~/content/products.json';import brands from '~/content/brands.json';const {ar,c}=useCopy();usePageSeo('المجموعات بالجملة','Wholesale collections');const route=useRoute();const search=ref(''),brand=ref(String(route.query.brand||'')),type=ref(''),gender=ref(''),age=ref(String(route.query.age||''));const filtered=computed(()=>products.filter(p=>(!search.value||[p.name.ar,p.name.en,p.code].join(' ').toLowerCase().includes(search.value.toLowerCase()))&&(!brand.value||p.brand===brand.value)&&(!type.value||p.type===type.value)&&(!gender.value||p.gender===gender.value)&&(!age.value||((p as any).ageTags||[]).includes(age.value))));const types=[['rompers','رومبرز','Rompers'],['sets','أطقم','Sets'],['dresses','فساتين','Dresses'],['pajamas','بيجامات','Pajamas'],['winter','شتاء','Winter'],['gift-sets','هدايا مواليد','Gift sets'],['adult','كبار (أحياناً)','Adults (occasional)']];const ages=sizeGroups;
</script>
<template><div class="container section" style="padding-top:0"><UiBreadcrumbs :title="c('المجموعات','Collections')"/><div class="page-intro"><span class="eyebrow">{{c('لأرفف محلك القادمة','FOR YOUR NEXT SEASON')}}</span><h1>{{c('اكتشف المجموعات.','Discover the collections.')}}</h1><p>{{c('ملابس أطفال بالجملة بفئات مولود، S–M–L، ٢–٥ سنوات و٦–١٢ سنة. الأسعار والتوفر والتعبئة عند الاستفسار.','Children’s clothing wholesale, Born Baby, S–M–L, 2–5 years and 6–12 years. Enquire for pricing, availability and packing.')}}</p></div><div class="filter-panel"><div class="filter-row"><input v-model="search" :placeholder="c('ابحث باسم القطعة أو الرمز','Search name or code')" :aria-label="c('بحث المنتجات','Search products')"/><select v-model="brand" :aria-label="c('العلامة','Brand')"><option value="">{{c('جميع العلامات','All brands')}}</option><option v-for="b in brands" :key="b.slug" :value="b.slug">{{b.name}}</option></select><select v-model="type" :aria-label="c('النوع','Type')"><option value="">{{c('جميع الأنواع','All types')}}</option><option v-for="[v,a,e] in types" :key="v" :value="v">{{c(a,e)}}</option></select><select v-model="gender" :aria-label="c('الفئة','Gender')"><option value="">{{c('جميع الفئات','All styles')}}</option><option value="boys">{{c('أولاد','Boys')}}</option><option value="girls">{{c('بنات','Girls')}}</option><option value="unisex">{{c('للجنسين','Unisex')}}</option></select><select v-model="age" :aria-label="c('المقاس','Size')"><option value="">{{c('جميع المقاسات','All sizes')}}</option><option v-for="[v,a,e] in ages" :key="v" :value="v">{{c(a,e)}}</option></select></div><div class="filter-count">{{filtered.length}} {{c('قطعة · الصور الموسومة كنموذج ليست مخزوناً مؤكداً','items · Preview designs are illustrative, not confirmed stock')}} <button class="text-link" style="background:none;margin-inline-start:20px" @click="search='';brand='';type='';gender='';age=''">{{c('مسح الفلاتر','Reset filters')}}</button></div></div><div v-if="filtered.length" class="product-grid"><UiProductCard v-for="p in filtered" :key="p.slug" :product="p"/></div><div v-else class="empty"><h2>{{c('لا توجد نتائج مؤكدة.','No matching items.')}}</h2><p>{{c('المقاسات تؤكد عند الاستفسار. جرّب تغيير الفلاتر أو تواصل معنا.','Sizes are confirmed on enquiry. Try adjusting your filters or contact us.')}}</p></div></div></template>
